#include <bits/stdc++.h>
using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;

    vector<long long> h(n);
    for(auto &x : h) cin >> x;

    // máximo prefixo (inclusivo) e máximo sufixo (inclusivo)
    vector<long long> pm(n), sm(n);
    pm[0] = h[0];
    for(int i = 1; i < n; i++) pm[i] = max(pm[i-1], h[i]);
    sm[n-1] = h[n-1];
    for(int i = n-2; i >= 0; i--) sm[i] = max(sm[i+1], h[i]);

    long long cnt = 0;
    for(int i = 0; i < n; i++){
        // nível de água na seção i após saturar
        long long lvl = min(pm[i], sm[i]);
        if(lvl - h[i] >= 1) cnt++;  // pelo menos 1m de profundidade
    }

    cout << cnt << "\n";
    return 0;
}
